    directoryVisible: true,
    sources: [{ id: "src_cerf_wikidata", kind: "wikidata", title: "Vint Cerf (Q92743) -- verified live via the Wikidata API (2026-10-11): English label 'Vint Cerf', description 'American computer scientist (born 1943)', born 23 June 1943, no date of death, citizenship United States, Korean label present. Orientation only; not used as support for any row.", url: "https://www.wikidata.org/wiki/Q92743" }, { id: "src_cerf_ethw", kind: "institution", title: "IEEE Milestones (Engineering and Technology History Wiki), 'Transmission Control Protocol (TCP) Enables the Internet, 1974', dedicated 20 May 2024 at Stanford -- IEEE milestone entry crediting Vinton Cerf and Robert Kahn as co-authors of the 1974 paper 'A Protocol for Packet Network Intercommunication', which described TCP linking multiple packet-switched networks; TCP was later split into TCP and IP, and TCP/IP was required on ARPANET on 1 January 1983. States that the work was the product of collaboration among many contributors. CANONICAL SIGNIFICANCE SOURCE (professional-society history of the contribution; honouring in tone, so not used for any behavioural row). Read in full.", url: "https://ethw.org/Milestones:Transmission_Control_Protocol_(TCP)_Enables_the_Internet,_1974" }, { id: "src_cerf_lemelson", kind: "institution", title: "Lemelson-MIT, 'Vinton Cerf' biography -- institutional biography: born 1943, Stanford mathematics degree and UCLA computer science master's and doctorate, Stanford assistant professor 1972-76, DARPA 1973-82 funding TCP/IP, packet radio and packet satellite groups, MCI Mail, Corporation for National Research Initiatives, Google from 2005, Jet Propulsion Laboratory interplanetary-internet work, ICANN chairman 2000-2007 and Internet Society president 1992-95, and honours including the 1997 National Medal of Technology, 2012 Internet Hall of Fame and 2013 Queen Elizabeth Prize for Engineering. Honouring institutional biography with no working-style description. Read in full.", url: "https://lemelson.mit.edu/resources/vinton-cerf" }, { id: "src_cerf_hlf", kind: "institution", title: "Heidelberg Laureate Forum, 'Vinton Gray Cerf' laureate page -- gives the 2004 ACM A.M. Turing Award, shared with Robert E. Kahn, 'for pioneering work on internetworking, including the design and implementation of the Internet's basic communications protocols, TCP/IP, and for inspired leadership in networking'. Brief institutional page used only to confirm the award and its citation (the ACM's own page returned HTTP 403). Read in full.", url: "https://www.heidelberg-laureate-forum.org/laureate/vinton-gray-cerf.html" }, { id: "src_cerf_networkworld", kind: "press", title: "Juan Carlos Perez, 'ICANN faces major transition with Cerf's departure', Network World, 29 June 2007 -- trade-press assessment of Cerf's tenure as ICANN chairman (board from 1999, chairman from 2000, leaving in October 2007 under term limits): consensus-building through early crises, political skill (Mark Uncapher), board stability (Milton Mueller), a registry executive saying his strong leadership sometimes led board members to vote with him even when he was wrong, and critics saying he took a very conservative approach, accepted U.S. control and let bureaucracy grow. Independent with mixed and critical voices. Read in full.", url: "https://www.networkworld.com/article/2292011/icann-faces-major-transition-with-cerf-s-departure.html" }, { id: "src_cerf_ap_icann", kind: "press", title: "Anick Jesdanun (Associated Press), 'A guiding force of the Internet steps down', Philadelphia Inquirer, 4 November 2007 -- wire profile of Cerf at the end of seven years as the unpaid ICANN chairman: ICANN survived power struggles and grew, ICANN CEO Paul Twomey's remark that Cerf has 'a certain star quality', can talk to anyone and explains how the Internet works to sceptical officials, his humour ('My sentence is up'), and continuing criticism that ICANN was arbitrary, secretive and slow. Independent, with a colleague's view and critical voices. Read in full.", url: "https://www.inquirer.com/philly/business/20071104_A_guiding_force_of_the_Internet_steps_down.html" }, { id: "src_cerf_pelkey", kind: "archive", title: "James Pelkey, 'A History of Computer Communications' interview page for Vint Cerf (interview recorded 8 February 1988 at CNRI, Reston), with the interviewer's summary -- describes Kahn's 1973 request that Cerf help design a host-to-host protocol interconnecting heterogeneous packet networks, the May 1974 paper, Cerf joining Kahn at ARPA's IPTO in September 1976 to manage the redesign into TCP/IP, and notes that Cerf consistently credited others and was gracious, engaging and someone people liked working with and for. Archive of an oral-history interview plus the interviewer's own appraisal, so partly self; used for collaboration only alongside other sources. The first 100,000 characters of the page were read; the last part was not.", url: "https://historyofcomputercommunications.info/interviews/Vint-Cerf/" }, { id: "src_cerf_quanta", kind: "press", title: "Susan D'Agostino, 'To Boldly Go Where No Internet Protocol Has Gone Before' (Cerf interview), Quanta Magazine, 21 October 2020 -- edited Q&A on the Interplanetary Internet: the spring 1998 meeting at JPL, Adrian Hooke pushing the idea and holding the team together, Cerf's conclusion that standard Internet protocols fail at interplanetary distances because of delay, the 2003 bundle protocols that let nodes store and forward data, building the network incrementally by reusing spacecraft, and Cerf saying 'a lot of people contributed to the creation of the internet'. The technical claims are largely Cerf's own account (self), with the interviewer's descriptions of him as playful and with 'a preacher's eagerness'. Personal health remarks in the piece were not used. Read in full.", url: "https://quantamagazine.org/vint-cerfs-plan-for-building-an-internet-in-space-20201021" }, { id: "src_cerf_techreview", kind: "press", title: "Brittany Sauser, 'A Better Network for Outer Space', MIT Technology Review, 27 October 2008 -- news report on the Interplanetary Internet effort led by Cerf with NASA's Jet Propulsion Laboratory and MITRE: a store-and-forward bundle protocol for delay- and disruption-tolerant networking, TCP/IP kept on planetary surfaces and inside spacecraft, reuse of existing spacecraft such as EPOXI by uploading new software, authentication between nodes and plans for a proposed international standard. Independent press reporting of plans, with Cerf quoted; it does not say whether the planned tests happened. Read in full.", url: "https://www.technologyreview.com/s/411092/a-better-network-for-outer-space/" }, { id: "src_cerf_commons", kind: "institution", title: "Wikimedia Commons file page 'Dr Vint Cerf ForMemRS.jpg' -- checked for the portrait's licence: photograph by Duncan Hull, 15 July 2016, credit 'The Royal Society', CC BY-SA 4.0 (the page also shows CC BY-SA 3.0 in its summary) with a Wikimedia VRT permission notice from the copyright holder. Not used for any scoring.", url: "https://commons.wikimedia.org/wiki/File:Dr_Vint_Cerf_ForMemRS.jpg" }],
